import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/28-Testing_Strategy.html","title":"测试与质量保障策略","lang":"en-US","frontmatter":{},"filePathRelative":"28-Testing_Strategy.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`28-Testing_Strategy.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="测试与质量保障策略" tabindex="-1"><a class="header-anchor" href="#测试与质量保障策略"><span>测试与质量保障策略</span></a></h1><blockquote><p>目的：为 Apollo MMORPG 项目建立系统化的测试体系，覆盖单元、集成、端到端、回归与自动化流程，确保快速迭代中保持质量。</p></blockquote><h2 id="_1-测试维度概览" tabindex="-1"><a class="header-anchor" href="#_1-测试维度概览"><span>1. 测试维度概览</span></a></h2><table><thead><tr><th>层级</th><th>描述</th><th>主要工具/方法</th></tr></thead><tbody><tr><td>单元测试 (UT)</td><td>独立函数/类、无外部依赖</td><td>Catch2、gTest、GoogleMock</td></tr><tr><td>组件测试 (CT)</td><td>模块内子系统（NetCore/AOI/DataProxy等）</td><td>自研模拟器、Mock Transport/DB</td></tr><tr><td>集成测试 (IT)</td><td>多服务协同（Gate+Zone+AOI+DataProxy）</td><td>Docker Compose/容器集群</td></tr><tr><td>端到端 (E2E)</td><td>客户端 SDK → Gate → Zone → DB 全链路</td><td>Unity 自动化脚本、C++ client</td></tr><tr><td>回归/灰度验证</td><td>更新后对关键场景回归 &amp; 数据对比</td><td>Pipeline 自动回放脚本</td></tr><tr><td>非功能测试</td><td>性能/压测、安全、容灾</td><td>参考 <code>docs/23</code>、<code>docs/21</code></td></tr></tbody></table><h2 id="_2-单元测试" tabindex="-1"><a class="header-anchor" href="#_2-单元测试"><span>2. 单元测试</span></a></h2><h3 id="_2-1-范围" tabindex="-1"><a class="header-anchor" href="#_2-1-范围"><span>2.1 范围</span></a></h3><ul><li>算法/容器：AOI 计算、属性计算、序列化。</li><li>网络编解码：包头、加密、校验。</li><li>DataProxy 序列化/分片逻辑。</li><li>插件加载、ApplicationContext 生命周期。</li></ul><h3 id="_2-2-策略" tabindex="-1"><a class="header-anchor" href="#_2-2-策略"><span>2.2 策略</span></a></h3><ul><li>使用 Catch2 + GoogleMock。</li><li>覆盖率指标（行/分支）60% 起步，核心模块 80%+。</li><li>引入 <code>ctest</code> 与 CI 集成，失败阻断合并。</li></ul><h2 id="_3-组件-模块测试" tabindex="-1"><a class="header-anchor" href="#_3-组件-模块测试"><span>3. 组件/模块测试</span></a></h2><h3 id="netcore" tabindex="-1"><a class="header-anchor" href="#netcore"><span>NetCore</span></a></h3><ul><li>搭建模拟客户端（C++），测试连接/重连/心跳/限流。</li><li>模拟异常（网络抖动、丢包），验证 SessionManager 行为。</li></ul><h3 id="aoi" tabindex="-1"><a class="header-anchor" href="#aoi"><span>AOI</span></a></h3><ul><li>离线构建场景数据（路径/随机移动），回放并检查 Enter/Leave 序列。</li><li>使用可视化工具（脚本）验证 AOI 视野正确性。</li></ul><h3 id="dataproxy" tabindex="-1"><a class="header-anchor" href="#dataproxy"><span>DataProxy</span></a></h3><ul><li>使用内存版 Redis/MySQL（或 Docker 中的真实实例），执行 Load/Save/并发写入。</li><li>模拟 DB 故障，验证写队列重试、WAL。</li></ul><h3 id="battle-service" tabindex="-1"><a class="header-anchor" href="#battle-service"><span>Battle Service</span></a></h3><ul><li>构造不同战斗脚本，检查 Pipeline 结果（HP、Buff、事件顺序）。</li><li>对比客户端模拟器的结算结果，确保 determinism。</li></ul><h2 id="_4-集成测试" tabindex="-1"><a class="header-anchor" href="#_4-集成测试"><span>4. 集成测试</span></a></h2><h3 id="_4-1-环境" tabindex="-1"><a class="header-anchor" href="#_4-1-环境"><span>4.1 环境</span></a></h3><ul><li>通过 Docker Compose 或 Kubernetes 部署 Gate/Zone/AOI/DataProxy/DB/Redis/Transport。</li><li>每日构建自动部署 Test 环境。</li></ul><h3 id="_4-2-场景" tabindex="-1"><a class="header-anchor" href="#_4-2-场景"><span>4.2 场景</span></a></h3><ul><li>登录/创建角色/进入场景。</li><li>玩家移动 + AOI 广播。</li><li>战斗流程（施法、伤害、结算）。</li><li>数据持久化/断线重连。</li><li>插件加载/卸载、配置热更新。</li></ul><h3 id="_4-3-自动化" tabindex="-1"><a class="header-anchor" href="#_4-3-自动化"><span>4.3 自动化</span></a></h3><ul><li>使用 Python/Golang 写模拟客户端脚本，调用 gRPC/HTTP 接口驱动场景。</li><li>集成测试后自动收集日志/指标，通过准入条件（如错误=0）控制合并。</li></ul><h2 id="_5-端到端测试-e2e" tabindex="-1"><a class="header-anchor" href="#_5-端到端测试-e2e"><span>5. 端到端测试 (E2E)</span></a></h2><h3 id="_5-1-unity-自动化" tabindex="-1"><a class="header-anchor" href="#_5-1-unity-自动化"><span>5.1 Unity 自动化</span></a></h3><ul><li>使用 Unity Test Runner/PlayMode Tests 驱动 SDK 调用。</li><li>脚本：登录/移动/战斗/退出/异常网络。</li><li>可在 CI 上运行（Headless Unity + Linux）。</li></ul><h3 id="_5-2-脚本化客户端" tabindex="-1"><a class="header-anchor" href="#_5-2-脚本化客户端"><span>5.2 脚本化客户端</span></a></h3><ul><li>C++/Go 客户端模拟器，可在无 UI 环境运行，支持协议 fuzz。</li></ul><h3 id="_5-3-数据校验" tabindex="-1"><a class="header-anchor" href="#_5-3-数据校验"><span>5.3 数据校验</span></a></h3><ul><li>测试完成后，将服务器 TLog/DB 数据与预期对比，确保逻辑正确。</li></ul><h2 id="_6-回归与发布验证" tabindex="-1"><a class="header-anchor" href="#_6-回归与发布验证"><span>6. 回归与发布验证</span></a></h2><h3 id="_6-1-回放脚本" tabindex="-1"><a class="header-anchor" href="#_6-1-回放脚本"><span>6.1 回放脚本</span></a></h3><ul><li>将关键场景录制为脚本（proto/log），每次发布前回放，保证行为一致。</li><li>Script runner 负责在测试环境执行，比较输出/日志。</li></ul><h3 id="_6-2-数据一致性" tabindex="-1"><a class="header-anchor" href="#_6-2-数据一致性"><span>6.2 数据一致性</span></a></h3><ul><li>发布后对比旧版本与新版本数据库快照、TLog，确保无异常波动。</li></ul><h3 id="_6-3-灰度验证" tabindex="-1"><a class="header-anchor" href="#_6-3-灰度验证"><span>6.3 灰度验证</span></a></h3><ul><li>在灰度环境使用真实玩家/机器人，观察监控/告警指标。</li></ul><h2 id="_7-自动化流水线" tabindex="-1"><a class="header-anchor" href="#_7-自动化流水线"><span>7. 自动化流水线</span></a></h2><h3 id="_7-1-ci-阶段" tabindex="-1"><a class="header-anchor" href="#_7-1-ci-阶段"><span>7.1 CI 阶段</span></a></h3><ol><li>代码检查（lint/格式/静态分析）。</li><li>单元测试。</li><li>构建产物。</li><li>组件测试（可选，异步）。</li></ol><h3 id="_7-2-cd-阶段" tabindex="-1"><a class="header-anchor" href="#_7-2-cd-阶段"><span>7.2 CD 阶段</span></a></h3><ol><li>部署 Test 环境，运行集成测试。</li><li>运行 E2E/性能测试（按需）。</li><li>部署 Staging，执行灰度脚本。</li><li>发布 Prod。</li></ol><h3 id="_7-3-工具" tabindex="-1"><a class="header-anchor" href="#_7-3-工具"><span>7.3 工具</span></a></h3><ul><li>GitHub Actions / GitLab CI / Jenkins。</li><li>Docker/K8s 作为测试环境载体。</li><li>Allure/TestRail 用于报告。</li></ul><h2 id="_8-缺陷管理与质量门禁" tabindex="-1"><a class="header-anchor" href="#_8-缺陷管理与质量门禁"><span>8. 缺陷管理与质量门禁</span></a></h2><ul><li>缺陷在 Jira/Issue 系统中跟踪，标注影响范围与修复计划。</li><li>质量门禁：若 UT/IT/E2E 任意环节失败，则阻止合并。</li><li>所有 bug 需有对应测试用例，防止回归。</li></ul><h2 id="_9-测试数据与-mock" tabindex="-1"><a class="header-anchor" href="#_9-测试数据与-mock"><span>9. 测试数据与 Mock</span></a></h2><ul><li>提供测试数据生成脚本（模拟玩家、装备、任务）。</li><li>对外部依赖（支付、第三方 SDK）使用 Mock 服务。</li><li>DataProxy 提供“内存模式”以方便测试。</li></ul><h2 id="_10-roadmap" tabindex="-1"><a class="header-anchor" href="#_10-roadmap"><span>10. Roadmap</span></a></h2><ol><li>建立 UT 框架与基础用例。</li><li>完成 NetCore/AOI/DataProxy 等模块的组件测试工具。</li><li>构建自动化集成环境（Docker Compose/K8s）。</li><li>完成 Unity SDK 自动化脚本与 C++ 客户端模拟器。</li><li>建立回放脚本、数据校验工具。</li><li>将所有测试纳入 CI/CD Pipeline，形成质量门禁。</li></ol><hr><p>通过该策略，项目可在迭代过程中保持质量可控，问题发现及时，并支撑自动化发布流程。***</p>`,54)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};